 3→import com.github.benmanes.caffeine.cache.Cache
 4→
 5→class DefaultLocalCache<ID : Any, V : Any>(
 6→    val cache: Cache<String, V>,
 7→    val keyPrefix: String,
 8→) : LocalCache<ID, V> {
 9→    override fun get(id: ID): V? = cache.getIfPresent(id.toKey())
10→
11→    override fun getAll(ids: Collection<ID>): Map<ID, V?> {
12→        val values: List<V?> =
13→            ids
14→                .map { id -> id.toKey() }
15→                .map { key -> cache.getIfPresent(key) }
16→
17→        return ids.zip(values).associate {
18→            it.first to it.second
19→        }
20→    }
21→
22→    override fun put(
23→        id: ID,
24→        value: V,
25→    ) {
26→        cache.put(id.toKey(), value)
27→    }
28→
29→    override fun putAll(values: Map<ID, V>) {
30→        values
31→            .map { it.key.toKey() to it.value }
32→            .toMap()
33→            .let { cache.putAll(it) }
34→    }
35→
36→    private fun ID.toKey(): String = "$keyPrefix:$this"
37→}
